<template>
  <div class="function-page-shell h-full min-h-0 font-sans">
    <div class="function-page-container space-y-6 after-sales-page">
      <header class="function-page-header">
        <div>
          <div class="function-page-eyebrow">
            <span class="material-symbols-outlined">support_agent</span>
            客户售后中心
          </div>
          <h1 class="function-page-title">售后管理</h1>
          <p class="function-page-desc">可关联订单或直接选择客户创建售后工单，统一处理咨询、故障研判、补发配件、上门维修和更换电机。</p>
        </div>
        <div>
          <el-button v-if="activeTab === 'tickets'" type="primary" :disabled="!canCreate" @click="openTicket()">
            <span class="material-symbols-outlined text-[18px]">add_circle</span>
            新建售后工单
          </el-button>
          <el-button v-else type="primary" :disabled="!canPartCreate" @click="openPart()">
            <span class="material-symbols-outlined text-[18px]">add_circle</span>
            新增配件
          </el-button>
        </div>
      </header>
      <section class="function-list-panel after-sales-list-panel">
    <el-tabs v-model="activeTab" @tab-change="loadActive">
      <el-tab-pane label="售后工单" name="tickets">
        <div class="function-filter-bar"><el-input v-model="ticketQuery.keyword" clearable placeholder="工单号、项目、客户或订单号" @keyup.enter="submitTicketQuery" /><el-select v-model="ticketQuery.status" clearable placeholder="全部状态"><el-option v-for="item in statusOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-select v-model="ticketQuery.ticketType" clearable placeholder="全部处理方式"><el-option v-for="item in typeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-date-picker v-model="ticketQuery.createdDateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="创建开始日期" end-placeholder="创建结束日期" /><el-button type="primary" @click="submitTicketQuery">查询</el-button><el-button :loading="ticketExporting" :disabled="ticketExporting" @click="exportTickets"><span class="material-symbols-outlined text-[18px]">download</span>导出</el-button></div>
        <el-table v-loading="ticketLoading" :data="tickets" class="function-table" @row-click="openDetail">
          <el-table-column prop="ticketNo" label="工单号" min-width="170" />
          <el-table-column label="项目 / 客户" min-width="230"><template #default="{ row }"><b>{{ row.projectName || '未填写项目' }}</b><p class="table-subtext">{{ row.customerName || '未填写客户' }} · {{ row.orderId || '未关联订单' }}</p></template></el-table-column>
          <el-table-column label="处理方式" width="120"><template #default="{ row }">{{ typeLabel(row.ticketType) }}</template></el-table-column>
          <el-table-column label="物流单号" min-width="180"><template #default="{ row }"><el-popover v-if="row.waybillNo" trigger="hover" placement="right-start" :width="360" :show-after="260" :hide-after="120" popper-class="after-sales-logistics-popover" @show="loadTicketLogisticsTracking(row)"><template #reference><button type="button" class="after-sales-waybill-trigger" @click.stop><span class="material-symbols-outlined" aria-hidden="true">local_shipping</span><span>{{ row.waybillNo }}</span></button></template><section class="after-sales-logistics-card" aria-live="polite"><header><span class="material-symbols-outlined" aria-hidden="true">local_shipping</span><b>{{ row.logisticsCompany || '物流信息' }}</b><em v-if="ticketLogisticsState(row).data">{{ ticketLogisticsState(row).data.stateLabel || '物流状态已更新' }}</em></header><div class="after-sales-logistics-waybill">单号：{{ row.waybillNo }}</div><div v-if="ticketLogisticsState(row).loading" class="after-sales-logistics-feedback"><span class="after-sales-logistics-spinner" />物流轨迹加载中</div><div v-else-if="ticketLogisticsState(row).errorMessage" class="after-sales-logistics-feedback is-error">{{ ticketLogisticsState(row).errorMessage }}</div><div v-else-if="ticketLogisticsState(row).data?.traces?.length" class="after-sales-logistics-traces"><div v-for="(trace, index) in ticketLogisticsState(row).data.traces" :key="`${trace.time || 'trace'}-${index}`" class="after-sales-logistics-trace" :class="{ latest: index === 0 }"><span /><div><time>{{ trace.time || '时间未知' }}</time><p>{{ trace.context || '物流状态已更新' }}</p><small v-if="trace.location">{{ trace.location }}</small></div></div></div><div v-else class="after-sales-logistics-feedback">{{ ticketLogisticsState(row).data?.latestContext || '暂未返回物流路径' }}</div></section></el-popover><span v-else class="text-slate-400">--</span></template></el-table-column>
          <el-table-column label="负责人" min-width="130"><template #default="{ row }">{{ row.assigneeName || '--' }}</template></el-table-column>
          <el-table-column label="状态" width="130"><template #default="{ row }"><el-tag :type="statusTag(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column>
          <el-table-column label="紧急程度" width="100"><template #default="{ row }">{{ priorityLabel(row.priority) }}</template></el-table-column>
          <el-table-column label="质保提示" min-width="160"><template #default="{ row }"><div class="warranty-status is-compact"><el-tag v-for="item in warrantyStates(row.openingDate)" :key="item.years" :type="item.type" effect="plain" size="small">{{ item.label }}</el-tag></div></template></el-table-column>
          <el-table-column label="操作" width="320" fixed="right"><template #default="{ row }"><template v-if="row.status === 'closed'"><el-button link type="primary" @click.stop="openDetail(row)">详情</el-button><el-button v-if="canUpdate" link type="primary" @click.stop="openTicket(row)">编辑</el-button><el-button link type="primary" :disabled="!canProcess" @click.stop="openFollowUp(row)">{{ row.followUpTime ? '查看回访' : '回访' }}</el-button></template><template v-else><el-button link type="primary" @click.stop="openDetail(row)">详情</el-button><el-button v-if="canProcess && row.status !== 'cancelled'" link type="primary" @click.stop="openAssign(row)">指派人员</el-button><el-button v-if="row.status === 'draft' && canUpdate" link type="primary" @click.stop="openTicket(row)">编辑</el-button><el-button v-if="row.status === 'draft' && canProcess" link type="success" @click.stop="startTicket(row)">开始处理</el-button><el-button v-if="row.status === 'waiting_outbound' && canOutbound" link type="success" @click.stop="outbound(row)">配件出库</el-button><el-button v-if="row.status === 'processing' && canProcess" link type="success" @click.stop="closeTicket(row)">结案</el-button></template></template></el-table-column>
        </el-table>
        <el-pagination class="mt-4 justify-end" background layout="total, prev, pager, next" :current-page="ticketQuery.pageNum" :page-size="ticketQuery.pageSize" :total="ticketTotal" @current-change="page => { ticketQuery.pageNum = page; loadTickets() }" />
      </el-tab-pane>
      <el-tab-pane v-if="canPartList" label="配件库 / 库存" name="parts">
        <div class="function-filter-bar"><el-input v-model="partQuery.keyword" clearable placeholder="配件编码、名称或规格" @keyup.enter="loadParts" /><el-button type="primary" @click="loadParts">查询</el-button></div>
        <el-table v-loading="partLoading" :data="parts" class="function-table"><el-table-column prop="partCode" label="配件编码" min-width="140" /><el-table-column label="配件" min-width="220"><template #default="{ row }"><b>{{ row.partName }}</b><p class="table-subtext">{{ row.modelSpec || '无规格' }}</p></template></el-table-column><el-table-column label="单价" width="105"><template #default="{ row }">{{ formatPrice(row.unitPrice) }}</template></el-table-column><el-table-column prop="unit" label="单位" width="80" /><el-table-column prop="stockQty" label="现存" width="90" /><el-table-column prop="safetyStock" label="安全库存" width="100" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.status === 1 ? 'success' : 'info'">{{ row.status === 1 ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{ row }"><el-button link type="primary" :disabled="!canPartUpdate" @click="openPart(row)">编辑</el-button><el-button link type="success" :disabled="!canStockIn" @click="openStockIn(row)">入库</el-button></template></el-table-column></el-table>
      </el-tab-pane>
    </el-tabs>
      </section>

    <el-drawer v-model="ticketEditorVisible" :title="ticketForm.id ? '编辑售后工单' : '新建售后工单'" size="min(94vw, 960px)" destroy-on-close class="after-sales-drawer">
      <el-form label-position="top"><section class="form-section"><h3>1. 订单与受理信息</h3><el-form-item label="关联订单（可选）"><el-select v-model="ticketForm.orderId" clearable filterable remote reserve-keyword placeholder="没有订单可直接留空" :remote-method="searchOrders" :loading="orderLoading" class="w-full" @change="selectOrder"><el-option v-for="item in orderOptions" :key="item.orderId" :label="`${item.projectName || '未命名项目'}｜${item.customerName || '未填写客户'}｜${item.orderId}`" :value="item.orderId" /></el-select></el-form-item><el-alert v-if="selectedOrder" type="info" :closable="false" show-icon><template #title>{{ selectedOrder.customerName }} · {{ selectedOrder.projectName }} <span class="ml-2 text-slate-500">{{ selectedOrder.customerPhone || '未留电话' }}</span></template></el-alert><el-alert v-else type="warning" :closable="false" show-icon title="没有可关联订单时，请选择或填写客户；保存后会同步到客户管理。" /><div class="form-grid"><el-form-item label="客户名称" required><el-select v-model="ticketForm.customerName" :disabled="Boolean(selectedOrder)" clearable filterable remote reserve-keyword allow-create default-first-option placeholder="搜索已有客户或输入新客户" :remote-method="searchCustomers" :loading="customerLoading" class="w-full" @change="selectCustomer"><el-option v-for="item in customerOptions" :key="item.id" :label="item.customerName" :value="item.customerName" /></el-select></el-form-item><el-form-item label="项目名称"><el-select v-model="ticketForm.projectName" :disabled="Boolean(selectedOrder)" clearable filterable allow-create default-first-option placeholder="选择已有项目或输入新项目" class="w-full"><el-option v-for="item in selectedCustomerProjects" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="联系人"><el-input v-model="ticketForm.contactName" /></el-form-item><el-form-item label="联系电话"><el-input v-model="ticketForm.contactPhone" /></el-form-item><el-form-item label="开业时间"><el-date-picker v-model="ticketForm.openingDate" type="date" value-format="YYYY-MM-DD" class="w-full" placeholder="请选择开业时间" /></el-form-item><el-form-item label="质保提示"><div class="warranty-status"><el-tag v-for="item in warrantyStates(ticketForm.openingDate)" :key="item.years" :type="item.type" effect="plain">{{ item.label }}</el-tag></div></el-form-item><el-form-item label="紧急程度"><el-select v-model="ticketForm.priority" class="w-full"><el-option v-for="item in priorityOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="实际地址"><el-input v-model="ticketForm.actualAddress" placeholder="项目实际所在地（关联订单后自动带入项目名称）" /></el-form-item><el-form-item label="服务地址"><el-input v-model="ticketForm.serviceAddress" placeholder="售后服务或上门地址" /></el-form-item></div><el-form-item label="问题描述" required><el-input v-model="ticketForm.problemDesc" type="textarea" :rows="3" placeholder="请描述客户反馈、故障现象和已采取的措施" /></el-form-item><el-form-item label="售后维修图片"><div class="repair-image-uploader"><div v-if="ticketForm.repairImages.length" class="repair-image-list"><article v-for="(image, index) in ticketForm.repairImages" :key="image.fileUrl" class="repair-image-item"><span class="material-symbols-outlined" aria-hidden="true">image</span><div><b :title="image.fileName">{{ image.fileName }}</b><small>{{ formatFileSize(image.fileSize) }}</small></div><el-button link type="primary" @click="previewRepairImage(image)">查看</el-button><el-button link type="danger" @click="ticketForm.repairImages.splice(index, 1)">移除</el-button></article></div><el-upload action="#" accept="image/png,image/jpeg,image/webp" :auto-upload="false" :show-file-list="false" :disabled="repairImageUploading || ticketForm.repairImages.length >= 9" :on-change="file => handleRepairImageUpload(file.raw)"><el-button :loading="repairImageUploading" :disabled="ticketForm.repairImages.length >= 9"><span class="material-symbols-outlined text-[18px]">add_photo_alternate</span>上传维修图片</el-button></el-upload><small class="repair-image-tip">支持 JPG、PNG、WebP，单张最大 5MB，最多 9 张（{{ ticketForm.repairImages.length }}/9）</small></div></el-form-item></section>
      <section class="form-section"><h3>2. 处理方式</h3><el-alert v-if="editingClosedTicket" type="info" :closable="false" class="mb-4" title="本次仅修订工单资料；已结案状态、审核记录、配件出库明细和库存记录不会改变。" /><el-radio-group v-model="ticketForm.ticketType" class="type-cards"><el-radio-button v-for="item in typeOptions" :key="item.value" :label="item.value">{{ item.label }}</el-radio-button></el-radio-group><el-form-item v-if="!editingClosedTicket" label="是否审核" class="mt-4"><el-switch v-model="ticketForm.approvalRequired" active-text="需审核后处理" inactive-text="无需审核" /></el-form-item><template v-if="ticketForm.ticketType === 'diagnosis'"><div class="form-grid mt-4"><el-form-item label="产品类型"><el-select v-model="ticketForm.diagnosisProduct" clearable filterable class="w-full" placeholder="请选择产品类型"><el-option v-for="item in diagnosisProductOptions" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="具体原因"><el-select v-model="ticketForm.diagnosisFault" clearable filterable class="w-full" placeholder="请选择具体原因"><el-option v-for="item in diagnosisFaultOptions" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="建议处理"><el-select v-model="ticketForm.diagnosisAction" clearable filterable class="w-full" placeholder="请选择建议处理"><el-option v-for="item in diagnosisActionOptions" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="研判补充说明"><el-input v-model="ticketForm.diagnosisRemark" type="textarea" :rows="3" placeholder="补充故障现象、判断依据或客户沟通情况" /></el-form-item></div><el-form-item label="建议处理方案"><el-input v-model="ticketForm.resolution" type="textarea" :rows="3" placeholder="选择补发、上门或更换电机后，可填写具体执行方案" /></el-form-item></template><div v-if="ticketForm.ticketType === 'consultation'" class="mt-4"><el-form-item label="答复 / 处理结论"><el-input v-model="ticketForm.resolution" type="textarea" :rows="3" /></el-form-item></div><div v-if="ticketForm.ticketType === 'on_site_repair'" class="form-grid mt-4"><el-form-item label="预约服务时间"><el-date-picker v-model="ticketForm.scheduledTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" class="w-full" /></el-form-item><el-form-item label="服务人员"><el-input v-model="ticketForm.technicianName" /></el-form-item><el-form-item label="维修金额（元）"><el-input-number v-model="ticketForm.repairAmount" :min="0" :precision="2" :step="100" controls-position="right" class="w-full" placeholder="请输入维修金额" /></el-form-item></div><div v-if="ticketForm.ticketType === 'motor_replacement'" class="form-grid mt-4"><el-form-item label="旧电机信息"><el-input v-model="ticketForm.oldMotorInfo" placeholder="型号、编号及故障情况" /></el-form-item><el-form-item label="旧电机回收"><el-switch v-model="ticketForm.returnOldMotor" active-text="需要回收" inactive-text="不回收" /></el-form-item><el-form-item label="旧电机退还数量"><el-input-number v-model="ticketForm.returnOldMotorQuantity" :min="0" :precision="0" controls-position="right" class="w-full" /></el-form-item></div></section>
      <section v-if="editableTicketParts" class="form-section"><div class="flex items-center justify-between"><h3>3. 配件明细</h3><el-button link type="primary" @click="addPartLine">添加配件</el-button></div><el-alert type="warning" :closable="false" title="保存后生成待出库工单；仓库确认出库时才扣减配件库存。" /><div v-for="(line, index) in ticketForm.parts" :key="index" class="part-line"><el-select v-model="line.partId" filterable placeholder="选择现有配件" class="part-select"><el-option v-for="part in partOptions" :key="part.id" :label="`${part.partName}｜${part.modelSpec || '无规格'}｜可用 ${part.stockQty}`" :value="part.id" /></el-select><el-select v-model="line.partLocation" clearable placeholder="配件地点" class="part-location-select"><el-option v-for="location in partLocationOptions" :key="location" :label="location" :value="location" /></el-select><el-input-number v-model="line.quantity" :min="1" /><el-input v-model="line.remark" placeholder="备注（可选）" /><el-button link type="danger" @click="ticketForm.parts.splice(index, 1)">删除</el-button></div><el-empty v-if="ticketForm.parts.length === 0" description="尚未选择配件" :image-size="56" /></section>
      <section v-if="ticketForm.ticketType !== 'consultation' && ticketForm.ticketType !== 'diagnosis'" class="form-section"><h3>{{ editableTicketParts ? '4' : '3' }}. 处理结果</h3><el-form-item label="处理结果 / 服务记录"><el-input v-model="ticketForm.resolution" type="textarea" :rows="3" /></el-form-item><div class="form-grid"><el-form-item label="物流公司"><el-input v-model="ticketForm.logisticsCompany" placeholder="如：顺丰、京东物流" /></el-form-item><el-form-item label="物流单号"><el-input v-model="ticketForm.waybillNo" placeholder="填写后可在工单列表查看物流轨迹" /></el-form-item></div></section></el-form>
      <template #footer><el-button @click="ticketEditorVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveTicket">保存工单</el-button></template>
    </el-drawer>

    <el-drawer v-model="partEditorVisible" :title="partForm.id ? '编辑配件' : '新增配件'" size="min(92vw, 560px)" destroy-on-close><el-form label-position="top"><el-alert title="配件建档只维护基础资料；现存数量仍请通过“入库”操作维护。" type="info" :closable="false" class="mb-4" /><div class="form-grid"><el-form-item label="编号"><el-input v-model="partForm.partCode" placeholder="保存后自动生成" disabled /></el-form-item><el-form-item label="名称" required><el-input v-model="partForm.partName" placeholder="请输入配件名称" /></el-form-item><el-form-item label="规格型号"><el-input v-model="partForm.modelSpec" placeholder="请输入规格型号" /></el-form-item><el-form-item label="单价"><el-input-number v-model="partForm.unitPrice" :min="0" :precision="2" :step="0.01" controls-position="right" class="w-full" placeholder="0.00" /></el-form-item><el-form-item label="单位"><el-input v-model="partForm.unit" placeholder="个" /></el-form-item></div><el-form-item label="配件图片"><el-upload drag action="#" accept="image/png,image/jpeg,image/webp" :auto-upload="false" :show-file-list="false" :disabled="partPhotoUploading" :on-change="file => handlePartPhotoUpload(file.raw)"><el-image v-if="partForm.photoUrl" :src="partForm.photoUrl" fit="cover" class="part-photo-preview" /><div v-else class="part-photo-placeholder">拖拽或点击上传配件图片<br><small>支持 JPG、PNG、WebP，最大 5MB</small></div></el-upload><el-button v-if="partForm.photoUrl" link type="danger" @click="partForm.photoUrl = ''">移除图片</el-button></el-form-item><el-form-item label="备注"><el-input v-model="partForm.remark" type="textarea" :rows="3" placeholder="填写配件说明、适用场景等" /></el-form-item></el-form><template #footer><el-button @click="partEditorVisible = false">取消</el-button><el-button type="primary" :loading="savingPart" @click="savePart">保存</el-button></template></el-drawer>
    <el-dialog v-model="stockInVisible" title="配件入库" width="420px"><p class="mb-4">{{ stockInPart?.partName }}（当前库存 {{ stockInPart?.stockQty || 0 }}）</p><el-form label-position="top"><el-form-item label="入库数量"><el-input-number v-model="stockInForm.quantity" :min="1" /></el-form-item><el-form-item label="备注"><el-input v-model="stockInForm.remark" /></el-form-item></el-form><template #footer><el-button @click="stockInVisible = false">取消</el-button><el-button type="primary" @click="stockIn">确认入库</el-button></template></el-dialog>
    <el-dialog v-model="assignVisible" title="指派售后人员" width="min(92vw, 440px)" destroy-on-close><el-alert title="保存后会向已授权订阅消息的人员发送一条售后待办提醒。" type="info" :closable="false" class="mb-4" /><el-form label-position="top"><el-form-item label="工单"><span>{{ assigningTicket?.ticketNo }} · {{ assigningTicket?.projectName }}</span></el-form-item><el-form-item label="指派给" required><el-select v-model="assignForm.assigneeUserId" filterable remote reserve-keyword placeholder="搜索姓名、部门或职位" :remote-method="searchAssignees" :loading="assigneeLoading" class="w-full"><el-option v-for="item in assigneeOptions" :key="item.id" :label="assigneeLabel(item)" :value="item.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="assignVisible = false">取消</el-button><el-button type="primary" :loading="assigning" @click="assignTicket">确认指派</el-button></template></el-dialog>
    <el-dialog v-model="followUpVisible" :title="followUpTicket?.followUpTime ? '回访记录' : '售后回访'" width="min(92vw, 520px)" destroy-on-close><el-form label-position="top"><el-form-item label="工单"><span>{{ followUpTicket?.ticketNo }} · {{ followUpTicket?.projectName }} · {{ followUpTicket?.customerName }}</span></el-form-item><div class="form-grid"><el-form-item label="回访时间" required><el-date-picker v-model="followUpForm.followUpTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" class="w-full" /></el-form-item><el-form-item label="客户满意度" required><el-select v-model="followUpForm.satisfaction" class="w-full" placeholder="请选择"><el-option v-for="item in followUpSatisfactionOptions" :key="item" :label="item" :value="item" /></el-select></el-form-item></div><el-form-item label="问题是否解决"><el-switch v-model="followUpForm.resolved" active-text="已解决" inactive-text="未解决" /></el-form-item><el-form-item label="回访内容" required><el-input v-model="followUpForm.content" type="textarea" :rows="4" placeholder="记录客户反馈、后续处理事项等" /></el-form-item></el-form><template #footer><el-button @click="followUpVisible = false">取消</el-button><el-button type="primary" :loading="savingFollowUp" @click="saveFollowUp">保存回访</el-button></template></el-dialog>
    <el-drawer v-model="detailVisible" title="售后工单详情" size="min(92vw, 680px)"><div v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="工单号">{{ detail.ticketNo }}</el-descriptions-item><el-descriptions-item label="状态">{{ statusLabel(detail.status) }}</el-descriptions-item><el-descriptions-item label="项目 / 客户">{{ detail.projectName || '未填写项目' }} / {{ detail.customerName || '未填写客户' }}</el-descriptions-item><el-descriptions-item label="关联订单">{{ detail.orderId || '未关联订单' }}</el-descriptions-item><el-descriptions-item label="负责人">{{ detail.assigneeName || '--' }}</el-descriptions-item><el-descriptions-item label="处理方式">{{ typeLabel(detail.ticketType) }}</el-descriptions-item><el-descriptions-item label="物流信息">{{ [detail.logisticsCompany, detail.waybillNo].filter(Boolean).join(' · ') || '--' }}</el-descriptions-item><el-descriptions-item label="质保提示" :span="2"><div class="warranty-status"><el-tag v-for="item in warrantyStates(detail.openingDate)" :key="item.years" :type="item.type" effect="plain">{{ item.label }}</el-tag></div></el-descriptions-item><el-descriptions-item v-if="detail.ticketType === 'on_site_repair'" label="维修金额">{{ detail.repairAmount == null ? '--' : `${detail.repairAmount} 元` }}</el-descriptions-item><el-descriptions-item v-if="detail.ticketType === 'motor_replacement'" label="旧电机退还数量">{{ detail.returnOldMotorQuantity ?? 0 }}</el-descriptions-item><el-descriptions-item label="问题描述" :span="2">{{ detail.problemDesc }}</el-descriptions-item><el-descriptions-item label="故障研判" :span="2">{{ detail.diagnosis || '--' }}</el-descriptions-item><el-descriptions-item label="处理结果" :span="2">{{ detail.resolution || '--' }}</el-descriptions-item><el-descriptions-item label="售后维修图片" :span="2"><div v-if="detail.repairImages?.length" class="repair-image-detail-list"><el-button v-for="image in detail.repairImages" :key="image.fileUrl" plain @click="previewRepairImage(image)"><span class="material-symbols-outlined text-[18px]">image</span>{{ image.fileName }}</el-button></div><span v-else>--</span></el-descriptions-item><el-descriptions-item v-if="detail.followUpTime" label="回访时间">{{ detail.followUpTime }}</el-descriptions-item><el-descriptions-item v-if="detail.followUpTime" label="客户满意度">{{ detail.followUpSatisfaction || '--' }}</el-descriptions-item><el-descriptions-item v-if="detail.followUpTime" label="回访结果">{{ detail.followUpResolved === 1 ? '已解决' : '未解决' }}</el-descriptions-item><el-descriptions-item v-if="detail.followUpTime" label="回访人">{{ detail.followUpOperatorName || '--' }}</el-descriptions-item><el-descriptions-item v-if="detail.followUpTime" label="回访内容" :span="2">{{ detail.followUpContent || '--' }}</el-descriptions-item></el-descriptions><h3 class="mt-6 mb-3 font-bold">配件明细</h3><el-table :data="detail.parts || []"><el-table-column prop="partCode" label="编码" /><el-table-column prop="partName" label="配件" /><el-table-column prop="partLocation" label="地点" /><el-table-column prop="quantity" label="数量" /><el-table-column prop="unit" label="单位" /><el-table-column label="状态"><template #default="{ row }">{{ row.lineStatus === 'outbound' ? '已出库' : '待出库' }}</template></el-table-column></el-table></div></el-drawer>
    <el-dialog v-model="repairImagePreviewVisible" :title="repairImagePreviewName || '售后维修图片'" width="min(92vw, 920px)" destroy-on-close @closed="releaseRepairImagePreview"><div class="repair-image-preview-dialog"><el-image v-if="repairImagePreviewUrl" :src="repairImagePreviewUrl" fit="contain" /></div></el-dialog>
    </div>
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import {
  ElAlert,
  ElButton,
  ElDatePicker,
  ElDescriptions,
  ElDescriptionsItem,
  ElDialog,
  ElDrawer,
  ElEmpty,
  ElForm,
  ElFormItem,
  ElImage,
  ElInput,
  ElInputNumber,
  ElMessage,
  ElMessageBox,
  ElOption,
  ElPagination,
  ElPopover,
  ElRadioButton,
  ElRadioGroup,
  ElSelect,
  ElSwitch,
  ElTable,
  ElTableColumn,
  ElTabPane,
  ElTabs,
  ElTag,
  ElUpload
} from 'element-plus'
import { useUserStore } from '@/stores/user'
import { downloadXlsxBlob } from '@/utils/excelDownload'
import { assignAfterSalesTicket, downloadAfterSalesRepairImage, exportAfterSalesTickets, followUpAfterSalesTicket, getAfterSalesAssigneeOptions, getAfterSalesCustomerOptions, getAfterSalesOrderOptions, getAfterSalesParts, getAfterSalesTicket, getAfterSalesTicketLogisticsTracking, getAfterSalesTickets, outboundAfterSalesTicket, saveAfterSalesPart, saveAfterSalesTicket, stockInAfterSalesPart, updateAfterSalesTicketStatus, uploadAfterSalesPartPhoto, uploadAfterSalesRepairImage } from './api/afterSales'

const userStore = useUserStore()
const activeTab = ref('tickets'); const tickets = ref([]); const parts = ref([]); const ticketLoading = ref(false); const partLoading = ref(false); const ticketTotal = ref(0); const saving = ref(false)
const ticketEditorVisible = ref(false); const partEditorVisible = ref(false); const stockInVisible = ref(false); const detailVisible = ref(false); const assignVisible = ref(false); const followUpVisible = ref(false); const detail = ref(null); const stockInPart = ref(null); const selectedOrder = ref(null); const orderOptions = ref([]); const orderLoading = ref(false); const selectedCustomer = ref(null); const customerOptions = ref([]); const customerLoading = ref(false); const partPhotoUploading = ref(false); const repairImageUploading = ref(false); const repairImagePreviewVisible = ref(false); const repairImagePreviewUrl = ref(''); const repairImagePreviewName = ref(''); const savingPart = ref(false); const assigning = ref(false); const savingFollowUp = ref(false); const assigneeLoading = ref(false); const assigneeOptions = ref([]); const assigningTicket = ref(null); const followUpTicket = ref(null); const ticketExporting = ref(false)
const canCreate = computed(() => userStore.hasPermission('after_sales:create')); const canUpdate = computed(() => userStore.hasPermission('after_sales:update')); const canProcess = computed(() => userStore.hasPermission('after_sales:process')); const canOutbound = computed(() => userStore.hasPermission('after_sales:part:outbound')); const canPartList = computed(() => userStore.hasPermission('after_sales:part:list')); const canPartCreate = computed(() => userStore.hasPermission('after_sales:part:create')); const canPartUpdate = computed(() => userStore.hasPermission('after_sales:part:update')); const canStockIn = computed(() => userStore.hasPermission('after_sales:part:stock-in'))
const ticketQuery = reactive({ pageNum: 1, pageSize: 10, keyword: '', status: '', ticketType: '', createdDateRange: [] }); const partQuery = reactive({ pageNum: 1, pageSize: 100, keyword: '' }); const stockInForm = reactive({ partId: null, quantity: 1, remark: '' }); const assignForm = reactive({ assigneeUserId: null }); const followUpForm = reactive({ followUpTime: '', satisfaction: '', resolved: true, content: '' })
const ticketLogisticsStates = reactive({})
const LOGISTICS_TRACKING_FAILURE_RETRY_MS = 30 * 1000
const blankTicket = () => ({ id: null, orderId: '', customerName: '', projectName: '', ticketType: 'diagnosis', priority: 'normal', problemDesc: '', contactName: '', contactPhone: '', actualAddress: '', serviceAddress: '', openingDate: '', approvalRequired: false, diagnosis: '', diagnosisProduct: '', diagnosisFault: '', diagnosisAction: '', diagnosisRemark: '', resolution: '', scheduledTime: '', technicianName: '', logisticsCompany: '', waybillNo: '', oldMotorInfo: '', returnOldMotor: false, returnOldMotorQuantity: 0, repairAmount: null, repairImages: [], parts: [] })
const ticketForm = reactive(blankTicket()); const blankPart = () => ({ id: null, partCode: '', partName: '', category: '', modelSpec: '', unitPrice: null, unit: '个', safetyStock: 0, photoUrl: '', remark: '' }); const partForm = reactive(blankPart())
const typeOptions = [{ value: 'consultation', label: '咨询' }, { value: 'diagnosis', label: '故障研判' }, { value: 'resend_parts', label: '补发配件' }, { value: 'on_site_repair', label: '上门维修' }, { value: 'motor_replacement', label: '更换电机' }]; const priorityOptions = [{ value: 'low', label: '低' }, { value: 'normal', label: '普通' }, { value: 'high', label: '高' }, { value: 'urgent', label: '紧急' }]; const statusOptions = [{ value: 'draft', label: '草稿' }, { value: 'pending_approval', label: '待售后审核' }, { value: 'waiting_outbound', label: '待配件出库' }, { value: 'processing', label: '处理中' }, { value: 'closed', label: '已结案' }, { value: 'cancelled', label: '已取消' }]
const diagnosisProductOptions = ['电动直轨', '电动弯轨', '电动卷帘', '绿创电机', '杜亚电机', '其他', '安装增补样板间']
const diagnosisFaultOptions = ['双开卡顿', '窗帘开合卡住', '面料抽丝', '卷帘制头损坏', '电动弯轨道（异响）', '滑轮磨损（卡顿异响）', '轨道脱落', '轨道变形', '行程丢失', '网络掉线（转客控厂家检修）', '遥控器电量低', '遥控面板故障', '电机故障', '皮带脱落', '弧形帘滑车断裂', '开合帘滑车断裂', '皮带断裂', '配件损坏/缺失', '其他']
const diagnosisActionOptions = ['发配件', '发配件（已过保）', '补发配件更换皮带等', '补发配件更换滑车主体', '上门维修', '安装自家师傅上门', '转电机厂家', '转客控厂家', '客诉问题汇报', '已过质保', '更换电机']
const followUpSatisfactionOptions = ['满意', '一般', '不满意']; const partLocationOptions = ['三车间', '二车间', '其他']; const partOptions = computed(() => parts.value.filter(item => item.status === 1)); const needsParts = computed(() => ['resend_parts', 'motor_replacement'].includes(ticketForm.ticketType))
const editingClosedTicket = computed(() => Boolean(ticketForm.id) && ticketForm.status === 'closed'); const editableTicketParts = computed(() => needsParts.value && !editingClosedTicket.value)
const selectedCustomerProjects = computed(() => selectedCustomer.value?.projectNames || [])
const typeLabel = (value) => typeOptions.find(item => item.value === value)?.label || value || '--'; const priorityLabel = (value) => priorityOptions.find(item => item.value === value)?.label || value || '--'; const statusLabel = (value) => statusOptions.find(item => item.value === value)?.label || value || '--'; const statusTag = (value) => ({ pending_approval: 'warning', waiting_outbound: 'warning', processing: 'primary', closed: 'success', cancelled: 'info' }[value] || '')
function warrantyStates(openingDate) { const text = String(openingDate || '').slice(0, 10); const opening = text ? new Date(`${text}T00:00:00`) : null; if (!opening || Number.isNaN(opening.getTime())) return [{ years: 'unknown', label: '未填写开业时间', type: 'info' }]; const today = new Date(); today.setHours(0, 0, 0, 0); return [1, 6].map(years => { const expiry = new Date(opening); expiry.setFullYear(expiry.getFullYear() + years); const days = Math.round((expiry.getTime() - today.getTime()) / 86400000); const state = days < 0 ? '已过保' : days === 0 ? '今日到期' : `质保中（剩余${days}天）`; return { years, label: `${years}年：${state}`, type: days < 0 ? 'danger' : days === 0 ? 'warning' : 'success' } }) }
function reset(target, source) { Object.keys(target).forEach(key => delete target[key]); Object.assign(target, source) }
function ticketQueryParams() { const [createdStartDate, createdEndDate] = ticketQuery.createdDateRange || []; return { pageNum: ticketQuery.pageNum, pageSize: ticketQuery.pageSize, keyword: ticketQuery.keyword || undefined, status: ticketQuery.status || undefined, ticketType: ticketQuery.ticketType || undefined, createdStartDate: createdStartDate || undefined, createdEndDate: createdEndDate || undefined } }
function submitTicketQuery() { ticketQuery.pageNum = 1; loadTickets() }
async function loadTickets() { ticketLoading.value = true; try { const data = await getAfterSalesTickets(ticketQueryParams()); tickets.value = data?.data || []; ticketTotal.value = Number(data?.total || 0) } catch { tickets.value = []; ticketTotal.value = 0 } finally { ticketLoading.value = false } }
async function exportTickets() { if (ticketExporting.value) return; ticketExporting.value = true; try { await downloadXlsxBlob(await exportAfterSalesTickets(ticketQueryParams()), `售后工单-${new Date().toISOString().slice(0, 10)}.xlsx`, (message) => ElMessage.error(message)) } finally { ticketExporting.value = false } }
function ticketLogisticsKey(ticket = {}) { return [ticket.id || '', ticket.logisticsCompany || '', ticket.waybillNo || '', ticket.updateTime || ''].join('|') }
function ticketLogisticsState(ticket = {}) { const key = ticketLogisticsKey(ticket); if (!ticketLogisticsStates[key]) ticketLogisticsStates[key] = { loading: false, data: null, errorMessage: '', retryAfter: 0 }; return ticketLogisticsStates[key] }
function ticketLogisticsCacheValid(data) { const expiresAt = Date.parse(data?.cacheExpiresAt || ''); return Number.isFinite(expiresAt) && expiresAt > Date.now() }
async function loadTicketLogisticsTracking(ticket = {}) { if (!ticket?.id || !ticket?.waybillNo) return; const state = ticketLogisticsState(ticket); if (state.loading || ticketLogisticsCacheValid(state.data) || state.retryAfter > Date.now()) return; state.loading = true; state.errorMessage = ''; try { state.data = await getAfterSalesTicketLogisticsTracking(ticket.id); state.retryAfter = 0 } catch (error) { state.data = null; state.retryAfter = Date.now() + LOGISTICS_TRACKING_FAILURE_RETRY_MS; state.errorMessage = error?.message || error?.msg || error?.response?.data?.msg || '物流查询失败，请稍后重试' } finally { state.loading = false } }
async function loadParts() { if (!canPartList.value) { parts.value = []; return }; partLoading.value = true; try { const data = await getAfterSalesParts(partQuery); parts.value = data?.data || [] } catch { parts.value = [] } finally { partLoading.value = false } }
function loadActive(tabName) { if (tabName === 'parts') { loadParts(); return } loadTickets() }
async function searchOrders(keyword = '') { orderLoading.value = true; try { orderOptions.value = await getAfterSalesOrderOptions({ keyword }) || [] } finally { orderLoading.value = false } }
async function searchCustomers(keyword = '') { customerLoading.value = true; try { customerOptions.value = await getAfterSalesCustomerOptions({ keyword }) || [] } finally { customerLoading.value = false } }
function selectCustomer(name) { const previous = selectedCustomer.value; selectedCustomer.value = customerOptions.value.find(item => item.customerName === name) || null; if (!selectedCustomer.value) { if (previous) { ticketForm.contactName = ''; ticketForm.contactPhone = ''; ticketForm.projectName = ''; ticketForm.actualAddress = ''; ticketForm.openingDate = '' } return } ticketForm.contactName = selectedCustomer.value.contactName || ''; ticketForm.contactPhone = selectedCustomer.value.contactPhone || ''; ticketForm.projectName = selectedCustomer.value.projectNames?.[0] || ''; ticketForm.actualAddress = selectedCustomer.value.customerAddress || ''; ticketForm.openingDate = selectedCustomer.value.openingDate || '' }
function selectOrder(id) { selectedOrder.value = orderOptions.value.find(item => item.orderId === id) || null; if (!selectedOrder.value) return; selectedCustomer.value = null; ticketForm.customerName = selectedOrder.value.customerName || ''; ticketForm.projectName = selectedOrder.value.projectName || ''; ticketForm.contactName = selectedOrder.value.contactName || ''; ticketForm.contactPhone = selectedOrder.value.contactPhone || selectedOrder.value.customerPhone || ''; ticketForm.actualAddress = selectedOrder.value.projectName ? `（${selectedOrder.value.projectName}）` : '' }
async function openTicket(row) {
  if (row?.id) {
    const data = await getAfterSalesTicket(row.id)
    reset(ticketForm, { ...blankTicket(), ...data, orderId: data.orderId || '', customerName: data.customerName || '', projectName: data.projectName || '', diagnosisRemark: data.diagnosis || '', returnOldMotor: Number(data.returnOldMotor) === 1, parts: (data.parts || []).map(item => ({ partId: item.partId, partLocation: item.partLocation || '', quantity: item.quantity, remark: item.remark || '' })) })
    selectedOrder.value = data.orderId ? { orderId: data.orderId, customerName: data.customerName, customerPhone: data.customerPhone, contactName: data.contactName, contactPhone: data.contactPhone, projectName: data.projectName } : null
    orderOptions.value = selectedOrder.value ? [selectedOrder.value] : []
    await searchCustomers(data.customerName || '')
    selectedCustomer.value = data.orderId ? null : customerOptions.value.find(item => item.customerName === data.customerName) || null
  } else {
    reset(ticketForm, blankTicket())
    selectedOrder.value = null
    selectedCustomer.value = null
    await Promise.all([searchOrders(), searchCustomers()])
  }
  await loadParts()
  ticketEditorVisible.value = true
}
function addPartLine() { ticketForm.parts.push({ partId: null, partLocation: '', quantity: 1, remark: '' }) }
function buildDiagnosis() { const values = [['产品类型', ticketForm.diagnosisProduct], ['故障类别', ticketForm.diagnosisFault], ['建议处理', ticketForm.diagnosisAction], ['补充说明', ticketForm.diagnosisRemark]].filter(([, value]) => value); return values.map(([label, value]) => `${label}：${value}`).join('；') }
async function saveTicket() { if (!ticketForm.problemDesc?.trim()) return ElMessage.warning('请填写问题描述'); if (!ticketForm.orderId && !ticketForm.customerName?.trim()) return ElMessage.warning('未关联订单时请填写客户名称'); saving.value = true; try { const payload = { ...ticketForm, orderId: ticketForm.orderId || null, customerName: ticketForm.customerName?.trim() || null, projectName: ticketForm.projectName?.trim() || null, problemDesc: ticketForm.problemDesc.trim(), diagnosis: ticketForm.ticketType === 'diagnosis' ? buildDiagnosis() : ticketForm.diagnosis, parts: needsParts.value ? ticketForm.parts : [] }; delete payload.diagnosisProduct; delete payload.diagnosisFault; delete payload.diagnosisAction; delete payload.diagnosisRemark; await saveAfterSalesTicket(payload); ElMessage.success('售后工单已保存'); ticketEditorVisible.value = false; loadTickets() } finally { saving.value = false } }
async function openDetail(row) { const data = await getAfterSalesTicket(row.id); detail.value = data; detailVisible.value = true }
function currentDateTimeValue() { const now = new Date(); now.setMinutes(now.getMinutes() - now.getTimezoneOffset()); return now.toISOString().slice(0, 19) }
async function openFollowUp(row) { const data = await getAfterSalesTicket(row.id); followUpTicket.value = data; reset(followUpForm, { followUpTime: data.followUpTime || currentDateTimeValue(), satisfaction: data.followUpSatisfaction || '', resolved: data.followUpTime ? data.followUpResolved === 1 : true, content: data.followUpContent || '' }); followUpVisible.value = true }
async function saveFollowUp() { if (!followUpForm.satisfaction || !followUpForm.content?.trim()) return ElMessage.warning('请选择客户满意度并填写回访内容'); savingFollowUp.value = true; try { await followUpAfterSalesTicket(followUpTicket.value.id, followUpForm); ElMessage.success('回访记录已保存'); followUpVisible.value = false; loadTickets() } finally { savingFollowUp.value = false } }
const assigneeLabel = (item) => [item.name, item.departmentName, item.positionName].filter(Boolean).join(' · ')
async function searchAssignees(keyword = '') { assigneeLoading.value = true; try { assigneeOptions.value = await getAfterSalesAssigneeOptions({ keyword }) || [] } finally { assigneeLoading.value = false } }
async function openAssign(row) { assigningTicket.value = row; assignForm.assigneeUserId = row.assigneeUserId || null; await searchAssignees(); if (row.assigneeUserId && !assigneeOptions.value.some(item => item.id === row.assigneeUserId) && row.assigneeName) assigneeOptions.value.unshift({ id: row.assigneeUserId, name: row.assigneeName }); assignVisible.value = true }
async function assignTicket() { if (!assignForm.assigneeUserId) return ElMessage.warning('请选择指派人员'); assigning.value = true; try { await assignAfterSalesTicket(assigningTicket.value.id, { assigneeUserId: assignForm.assigneeUserId }); ElMessage.success('售后工单已指派，并已发送订阅提醒'); assignVisible.value = false; loadTickets() } finally { assigning.value = false } }
async function outbound(row) { await ElMessageBox.confirm(`确认对工单 ${row.ticketNo} 的全部待出库配件执行出库？`, '确认出库', { type: 'warning' }); await outboundAfterSalesTicket(row.id); ElMessage.success('配件已出库，工单进入处理中'); loadTickets() }
async function startTicket(row) { await updateAfterSalesTicketStatus({ ticketId: row.id, action: 'start' }); ElMessage.success('工单已进入处理中'); loadTickets() }
async function closeTicket(row) { const { value } = await ElMessageBox.prompt('请填写处理结果', '售后结案', { inputType: 'textarea', inputPlaceholder: '客户确认情况、维修结果等' }); await updateAfterSalesTicketStatus({ ticketId: row.id, action: 'close', resolution: value }); ElMessage.success('工单已结案'); loadTickets() }
function openPart(row) { reset(partForm, { ...blankPart(), ...row }); partEditorVisible.value = true }
async function handlePartPhotoUpload(file) { if (!file || partPhotoUploading.value) return; if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) return ElMessage.warning('仅支持 JPG、PNG、WebP 格式图片'); if (file.size > 5 * 1024 * 1024) return ElMessage.warning('配件图片不能超过 5MB'); partPhotoUploading.value = true; try { const data = new FormData(); data.append('file', file); const result = await uploadAfterSalesPartPhoto(data); partForm.photoUrl = result.fileUrl || ''; ElMessage.success('配件图片上传成功') } finally { partPhotoUploading.value = false } }
async function handleRepairImageUpload(file) { if (!file || repairImageUploading.value) return; if (ticketForm.repairImages.length >= 9) return ElMessage.warning('维修图片最多上传 9 张'); if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type)) return ElMessage.warning('维修图片仅支持 JPG、PNG、WebP 格式'); if (file.size > 5 * 1024 * 1024) return ElMessage.warning('单张维修图片不能超过 5MB'); repairImageUploading.value = true; try { const data = new FormData(); data.append('file', file); const result = await uploadAfterSalesRepairImage(data); ticketForm.repairImages.push({ fileName: result.fileName || file.name, fileUrl: result.fileUrl, fileSize: result.fileSize ?? file.size }); ElMessage.success('维修图片上传成功') } finally { repairImageUploading.value = false } }
function formatFileSize(value) { const bytes = Number(value); if (!Number.isFinite(bytes) || bytes < 0) return '大小未知'; if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`; return `${(bytes / 1024 / 1024).toFixed(1)} MB` }
function releaseRepairImagePreview() { if (repairImagePreviewUrl.value) URL.revokeObjectURL(repairImagePreviewUrl.value); repairImagePreviewUrl.value = ''; repairImagePreviewName.value = '' }
async function previewRepairImage(image) { if (!image?.fileUrl) return; releaseRepairImagePreview(); const blob = await downloadAfterSalesRepairImage({ url: image.fileUrl, name: image.fileName }); repairImagePreviewUrl.value = URL.createObjectURL(blob); repairImagePreviewName.value = image.fileName || '售后维修图片'; repairImagePreviewVisible.value = true }
async function savePart() { if (!partForm.partName) return ElMessage.warning('请填写配件名称'); savingPart.value = true; try { await saveAfterSalesPart(partForm); ElMessage.success('配件已保存'); partEditorVisible.value = false; loadParts() } finally { savingPart.value = false } }
const formatPrice = (value) => value === null || value === undefined || value === '' ? '--' : `¥${Number(value).toFixed(2)}`
function openStockIn(row) { stockInPart.value = row; reset(stockInForm, { partId: row.id, quantity: 1, remark: '' }); stockInVisible.value = true }
async function stockIn() { await stockInAfterSalesPart(stockInForm); ElMessage.success('配件已入库'); stockInVisible.value = false; loadParts() }
onMounted(loadTickets)
onBeforeUnmount(releaseRepairImagePreview)
</script>

